struct BackgroundView: UIViewRepresentable { func makeCoordinator() -> Coordinator { Coordinator(self) }
func makeUIView(context: Context) -> MTKView {
    let view = MTKView()
    view.device = MTLCreateSystemDefaultDevice()
    view.delegate = context.coordinator
    view.preferredFramesPerSecond = 60
    view.enableSetNeedsDisplay = true
    view.isOpaque = false
    view.backgroundColor = .clear
    view.colorPixelFormat = .bgra8Unorm
    view.depthStencilPixelFormat = .invalid
    context.coordinator.setup(view: view)
    return view
}

func updateUIView(_ uiView: MTKView, context: Context) {
    uiView.setNeedsDisplay()
}

class Coordinator: NSObject, MTKViewDelegate {
    var parent: BackgroundView
    var commandQueue: MTLCommandQueue?
    var pipelineState: MTLRenderPipelineState?
    var vertexBuffer: MTLBuffer?
    var indexBuffer: MTLBuffer?
    var uniformsBuffer: MTLBuffer?
    var startTime = Date()
    var numIndices: Int = 0

    init(_ parent: BackgroundView) {
        self.parent = parent
    }

    func setup(view: MTKView) {
        guard let device = view.device else { return }
        commandQueue = device.makeCommandQueue()

        let library = try? device.makeLibrary(source: metalShaderSource, options: nil)
        let vertexFunction = library?.makeFunction(name: "vertex_main")
        let fragmentFunction = library?.makeFunction(name: "fragment_main")

        let pipelineDescriptor = MTLRenderPipelineDescriptor()
        pipelineDescriptor.vertexFunction = vertexFunction
        pipelineDescriptor.fragmentFunction = fragmentFunction
        pipelineDescriptor.colorAttachments[0].pixelFormat = view.colorPixelFormat
        pipelineDescriptor.colorAttachments[0].isBlendingEnabled = true
        pipelineDescriptor.colorAttachments[0].sourceRGBBlendFactor = .sourceAlpha
        pipelineDescriptor.colorAttachments[0].sourceAlphaBlendFactor = .sourceAlpha
        pipelineDescriptor.colorAttachments[0].destinationRGBBlendFactor = .oneMinusSourceAlpha
        pipelineDescriptor.colorAttachments[0].destinationAlphaBlendFactor = .oneMinusSourceAlpha

        let vertexDescriptor = MTLVertexDescriptor()
        vertexDescriptor.attributes[0].format = .float3
        vertexDescriptor.attributes[0].offset = 0
        vertexDescriptor.attributes[0].bufferIndex = 0
        vertexDescriptor.attributes[1].format = .float2
        vertexDescriptor.attributes[1].offset = MemoryLayout>.stride
        vertexDescriptor.attributes[1].bufferIndex = 0
        vertexDescriptor.layouts[0].stride = MemoryLayout.stride
        pipelineDescriptor.vertexDescriptor = vertexDescriptor

        pipelineState = try? device.makeRenderPipelineState(descriptor: pipelineDescriptor)

        let width: Int = 101
        let height: Int = 101
        var vertices: [Vertex] = []
        for y in 0...stride, options: [])

        var indices: [UInt32] = []
        for y in 0...stride, options: [])

        uniformsBuffer = device.makeBuffer(length: MemoryLayout.stride, options: .cpuCacheModeWriteCombined)
    }

    func mtkView(_ view: MTKView, drawableSizeWillChange size: CGSize) {}

    func draw(in view: MTKView) {
        guard let drawable = view.currentDrawable,
              let commandBuffer = commandQueue?.makeCommandBuffer(),
              let renderPassDescriptor = view.currentRenderPassDescriptor,
              let encoder = commandBuffer.makeRenderCommandEncoder(descriptor: renderPassDescriptor),
              let pipelineState = pipelineState,
              let vertexBuffer = vertexBuffer,
              let indexBuffer = indexBuffer,
              let uniformsBuffer = uniformsBuffer else { return }

        let time = Float(Date().timeIntervalSince(startTime))

        let aspect = Float(view.drawableSize.width / view.drawableSize.height)
        let projectionMatrix = matrix_perspective_right_hand_zero_to_one_fov(fovyRadians: Float.pi / 2.4, aspect: aspect, nearZ: 0.1, farZ: 1000)
        var modelMatrix = matrix_identity_float4x4
        modelMatrix = matrix_multiply(modelMatrix, matrix_rotation_x(angle: -Float.pi / 4.5))
        let viewMatrix = matrix_look_at_right_hand(eye: SIMD3(0,0,3.5), center: SIMD3(0,0,0), up: SIMD3(0,1,0))
        let modelViewMatrix = matrix_multiply(viewMatrix, modelMatrix)

        var uniforms = Uniforms(projectionMatrix: projectionMatrix, modelViewMatrix: modelViewMatrix, time: time)
        uniformsBuffer.contents().copyMemory(from: &uniforms, byteCount: MemoryLayout.stride)

        encoder.setRenderPipelineState(pipelineState)
        encoder.setVertexBuffer(vertexBuffer, offset: 0, index: 0)
        encoder.setVertexBuffer(uniformsBuffer, offset: 0, index: 1)
        encoder.setFragmentBuffer(uniformsBuffer, offset: 0, index: 0)
        encoder.drawIndexedPrimitives(type: .triangle, indexCount: numIndices, indexType: .uint32, indexBuffer: indexBuffer, indexBufferOffset: 0)

        encoder.endEncoding()
        commandBuffer.present(drawable)
        commandBuffer.commit()
    }
}
}
