using namespace metal;
float3 mod289(float3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; } float2 mod289(float2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; } float3 permute(float3 x) { return mod289(((x34.0)+1.0)x); } float snoise(float2 v) { constant float4 C = float4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439); float2 i = floor(v + dot(v, C.yy) ); float2 x0 = v - i + dot(i, C.xx); float2 i1; i1 = (x0.x > x0.y) ? float2(1.0, 0.0) : float2(0.0, 1.0); float4 x12 = x0.xyxy + C.xxzz; x12.xy -= i1; i = mod289(i); float3 p = permute( permute( i.y + float3(0.0, i1.y, 1.0 )) + i.x + float3(0.0, i1.x, 1.0 )); float3 m = max(0.5 - float3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0); m = mm; m = mm; float3 x = 2.0 * fract(p * C.www) - 1.0; float3 h = abs(x) - 0.5; float3 ox = floor(x + 0.5); float3 a0 = x - ox; m = 1.79284291400159 - 0.85373472095314 * ( a0a0 + h*h ); float3 g; g.x = a0.x * x0.x + h.x * x0.y; g.yz = a0.yz * x12.xz + h.yz * x12.yw; return 130.0 * dot(m, g); }
struct VertexOut { float4 position [[position]]; float2 uv [[user(uv)]]; };
struct Uniforms { float4x4 projectionMatrix; float4x4 modelViewMatrix; float time; };
vertex VertexOut vertex_main(device packed_float3 *positions [[buffer(0)]], device packed_float2 *uvs [[buffer(2)]], constant Uniforms &uniforms [[buffer(1)]], uint vid [[vertex_id]]) { VertexOut out; float3 pos = positions[vid]; float noise = snoise(float2(pos.x * 0.1, pos.y * 0.1) + uniforms.time * 0.05); float noise2 = snoise(float2(pos.x * 0.5, pos.y * 0.5) + uniforms.time * 0.025); pos.z = (noise + noise2) * 0.2; out.position = uniforms.projectionMatrix * uniforms.modelViewMatrix * float4(pos, 1.0); out.uv = uvs[vid]; return out; }
fragment float4 fragment_main(VertexOut in [[stage_in]], constant Uniforms &uniforms [[buffer(0)]]) { float3 color1 = float3(0.0, 0.2, 0.5); float3 color2 = float3(0.0, 0.48, 1.0); float3 specular = float3(0.8, 0.9, 1.0);
float noise = snoise(in.uv * 3.0 + uniforms.time * 0.05);
float mix_val = (noise + 1.0) * 0.5;
float3 final_color = mix(color1, color2, mix_val);
float shine = smoothstep(0.7, 0.8, noise);
final_color = mix(final_color, specular, shine * 0.5);

return float4(final_color, 1.0);
} “””
func matrix_perspective_right_hand_zero_to_one_fov(fovyRadians: Float, aspect: Float, nearZ: Float, farZ: Float) -> simd_float4x4 { let ys = 1 / tanf(fovyRadians / 2) let xs = ys / aspect let zs = farZ / (nearZ - farZ) let ws = zs * nearZ return simd_float4x4( SIMD4(xs, 0, 0, 0), SIMD4(0, ys, 0, 0), SIMD4(0, 0, zs, -1), SIMD4(0, 0, ws, 0) ) }
func matrix_look_at_right_hand(eye: SIMD3, center: SIMD3, up: SIMD3) -> simd_float4x4 { let f = normalize(center - eye) let s = normalize(cross(f, up)) let u = cross(s, f) return simd_float4x4( SIMD4(s.x, u.x, -f.x, 0), SIMD4(s.y, u.y, -f.y, 0), SIMD4(s.z, u.z, -f.z, 0), SIMD4(-dot(s, eye), -dot(u, eye), dot(f, eye), 1) ) }
func matrix_rotation_x(angle: Float) -> simd_float4x4 { let c = cos(angle) let s = sin(angle) return simd_float4x4( SIMD4(1, 0, 0, 0), SIMD4(0, c, s, 0), SIMD4(0, -s, c, 0), SIMD4(0, 0, 0, 1) ) }
