class ViewModel: ObservableObject { @Published var messages: [Message] = [] @Published var inputText: String = “” @Published var currentMode: String = “chat” @Published var isSendingDisabled: Bool = true @Published var researchTasks: [ResearchTask] = [] @Published var activeTaskId: String? @Published var showResearchOptions: Bool = false @Published var pendingResearchGoal: String = “” @Published var showPopupMenu: Bool = false @Published var researchActive: Bool = false
let exaApiKey: String = ""
let exaAnswerUrl = URL(string: "")!
let exaSearchUrl = URL(string: "")!
let exaFindSimilarUrl = URL(string: "")!
let exaResearchBaseUrl = URL(string: "")!

init() {
    messages.append(Message(text: try! AttributedString(markdown: "Üdvözlöm. Alapértelmezetten az Exa Answer API-t használom. Kattintson a '+' gombra a többi Exa funkció (Keresés, Hasonló link, Mély Kutatás) eléréséhez."), sender: "ai", isError: false, isTyping: false))
}

func handleSubmit() {
    let prompt = inputText.trimmingCharacters(in: .whitespacesAndNewlines)
    if prompt.isEmpty { return }
    inputText = ""
    isSendingDisabled = true
    addMessage(text: prompt, sender: "user")

    Task {
        do {
            switch currentMode {
            case "chat", "answer":
                try await sendExaAnswer(prompt: prompt)
            case "search":
                try await sendExaSearch(prompt: prompt)
            case "findsimilar":
                try await sendExaFindSimilar(prompt: prompt)
            case "research":
                pendingResearchGoal = prompt
                showResearchOptions = true
            default:
                break
            }
        } catch {
            updateLastTypingMessage(newText: "Hiba történt: \(error.localizedDescription)", isError: true)
        }
        if currentMode != "research" {
            currentMode = "chat"
        }
    }
}

func addMessage(text: String, sender: String, isError: Bool = false, isTyping: Bool = false) {
    var attr: AttributedString
    do {
        attr = try AttributedString(markdown: text)
    } catch {
        attr = AttributedString(text)
    }
    messages.append(Message(text: attr, sender: sender, isError: isError, isTyping: isTyping))
}

func addTypingIndicator() {
    messages.append(Message(text: AttributedString(""), sender: "ai", isError: false, isTyping: true))
}

func updateLastTypingMessage(newText: String, isError: Bool = false) {
    if let index = messages.lastIndex(where: { $0.isTyping }) {
        var attr: AttributedString
        do {
            attr = try AttributedString(markdown: newText)
        } catch {
            attr = AttributedString(newText)
        }
        messages[index] = Message(text: attr, sender: "ai", isError: isError, isTyping: false)
    } else {
        addMessage(text: newText, sender: "ai", isError: isError)
    }
}

func sendExaAnswer(prompt: String) async throws {
    addTypingIndicator()
    var request = URLRequest(url: exaAnswerUrl)
    request.httpMethod = "POST"
    request.setValue("application/json", forHTTPHeaderField: "Content-Type")
    request.setValue(exaApiKey, forHTTPHeaderField: "x-api-key")
    let payload = ["query": prompt, "text": true]
    request.httpBody = try JSONSerialization.data(withJSONObject: payload)
    let (data, _) = try await URLSession.shared.data(for: request)
    let response = try JSONDecoder().decode(ExaAnswerResponse.self, from: data)
    let formatted = formatExaAnswer(response: response)
    updateLastTypingMessage(newText: formatted)
}

func sendExaSearch(prompt: String) async throws {
    addTypingIndicator()
    var request = URLRequest(url: exaSearchUrl)
    request.httpMethod = "POST"
    request.setValue("application/json", forHTTPHeaderField: "Content-Type")
    request.setValue(exaApiKey, forHTTPHeaderField: "x-api-key")
    let payload = ["query": prompt, "numResults": 5, "text": true]
    request.httpBody = try JSONSerialization.data(withJSONObject: payload)
    let (data, _) = try await URLSession.shared.data(for: request)
    let response = try JSONDecoder().decode(ExaSearchResponse.self, from: data)
    let formatted = formatExaResults(results: response.results, title: "Keresési Találatok")
    updateLastTypingMessage(newText: formatted)
}

func sendExaFindSimilar(prompt: String) async throws {
    addTypingIndicator()
    var request = URLRequest(url: exaFindSimilarUrl)
    request.httpMethod = "POST"
    request.setValue("application/json", forHTTPHeaderField: "Content-Type")
    request.setValue(exaApiKey, forHTTPHeaderField: "x-api-key")
    let payload = ["url": prompt, "numResults": 5, "text": true]
    request.httpBody = try JSONSerialization.data(withJSONObject: payload)
    let (data, _) = try await URLSession.shared.data(for: request)
    let response = try JSONDecoder().decode(ExaSearchResponse.self, from: data)
    let formatted = formatExaResults(results: response.results, title: "Hasonló Linkek")
    updateLastTypingMessage(newText: formatted)
}

