func startExaResearchTask(goal: String) {
    let tempId = "temp_\(Date().timeIntervalSince1970)"
    let task = ResearchTask(id: tempId, goal: goal)
    researchTasks.append(task)
    addResearchWidgetMessage(task: task)

    Task {
        do {
            var request = URLRequest(url: exaResearchBaseUrl)
            request.httpMethod = "POST"
            request.setValue("application/json", forHTTPHeaderField: "Content-Type")
            request.setValue(exaApiKey, forHTTPHeaderField: "x-api-key")
            let payload = ["instructions": goal, "model": "exa-research"]
            request.httpBody = try JSONSerialization.data(withJSONObject: payload)
            let (data, _) = try await URLSession.shared.data(for: request)
            let exaTask = try JSONDecoder().decode(ExaResearchResponse.self, from: data)
            await MainActor.run {
                task.id = exaTask.researchId
                task.status = exaTask.status
                task.progress = 5
                task.subAgents = [SubAgent(name: "Kutató Agent", status: "Inicializálás...", progress: 5)]
                updateResearchWidget(task: task)
                pollResearchStatus(task: task)
            }
        } catch {
            await MainActor.run {
                task.status = "❌ Hiba a feladat indításakor: \(error.localizedDescription)"
                task.progress = 0
                updateResearchWidget(task: task)
            }
        }
    }
}

func pollResearchStatus(task: ResearchTask) {
    task.pollTimer = Timer.scheduledTimer(withTimeInterval: 4.0, repeats: true) { _ in
        Task {
            do {
                let url = self.exaResearchBaseUrl.appendingPathComponent("/\(task.id)?events=true")
                var request = URLRequest(url: url)
                request.setValue(self.exaApiKey, forHTTPHeaderField: "x-api-key")
                let (data, _) = try await URLSession.shared.data(for: request)
                let exaTask = try JSONDecoder().decode(ExaResearchStatus.self, from: data)
                await MainActor.run {
                    task.status = exaTask.status
                    if exaTask.status == "running" {
                        task.progress = min(95, task.progress + 5)
                        if !exaTask.events.isEmpty {
                            task.status = exaTask.events.last!.summary ?? "Folyamatban..."
                            task.subAgents = exaTask.events.map { e in
                                SubAgent(name: e.agentName ?? "Lépés", status: e.summary, progress: e.status == "completed" ? 100 : (e.status == "running" ? 50 : 0))
                            }
                        } else {
                            task.subAgents = [SubAgent(name: "Kutató Agent", status: "Kutatás...", progress: task.progress)]
                        }
                    } else if exaTask.status == "completed" {
                        task.pollTimer?.invalidate()
                        task.progress = 100
                        task.status = "Befejezve"
                        do {
                            task.report = try AttributedString(markdown: exaTask.output)
                        } catch {
                            task.report = AttributedString(exaTask.output)
                        }
                        let citations = exaTask.citations ?? []
                        task.similarLinks = citations.map { LinkItem(title: $0.title, url: $0.url, category: nil) }
                        task.webset = citations.map { LinkItem(title: $0.title, url: $0.url, category: "Forrás") }
                        task.subAgents = task.subAgents.map { SubAgent(name: $0.name, status: "Befejezve", progress: 100) }
                    } else if exaTask.status == "failed" {
                        task.pollTimer?.invalidate()
                        task.progress = 100
                        task.status = "❌ Hiba: \(exaTask.error ?? "Ismeretlen hiba")"
                        task.report = AttributedString("A feladat sikertelen: \(exaTask.error ?? "Részletek nem elérhetők.")")
                        task.subAgents = [SubAgent(name: "Agent", status: "Sikertelen", progress: 100)]
                    }
                    self.objectWillChange.send()
                    if self.activeTaskId == task.id {
                        // Update view
                    }
                }
            } catch {
                await MainActor.run {
                    task.status = "❌ Hiba: Lekérdezés sikertelen (\(error.localizedDescription))."
                    task.pollTimer?.invalidate()
                    self.objectWillChange.send()
                }
            }
        }
    }
}

