        view.delegate = context.coordinator
        view.preferredFramesPerSecond = 60
        view.enableSetNeedsDisplay = false
        view.isPaused = false
        view.isOpaque = false
        view.backgroundColor = .clear
        view.colorPixelFormat = .bgra8Unorm
        view.depthStencilPixelFormat = .invalid
        view.framebufferOnly = true
        context.coordinator.setup(view: view)
        return view
    }
    func updateUIView(_ uiView: MTKView, context: Context) {}
    class Coordinator: NSObject, MTKViewDelegate {
        var parent: BackgroundView
        var commandQueue: MTLCommandQueue?
        var pipelineState: MTLRenderPipelineState?
        var vertexBuffer: MTLBuffer?
        var indexBuffer: MTLBuffer?
        var uniformsBuffer: MTLBuffer?
        var startTime = Date()
        var numIndices: Int = 0
        init(_ parent: BackgroundView) {
            self.parent = parent
        }
        func setup(view: MTKView) {
            guard let device = view.device else { return }
            commandQueue = device.makeCommandQueue()
            let library = try? device.makeLibrary(source: metalShaderSource, options: nil)
            guard let vertexFunction = library?.makeFunction(name: "vertex_main"),
                  let fragmentFunction = library?.makeFunction(name: "fragment_main") else { return }
            let vertexDescriptor = MTLVertexDescriptor()
            vertexDescriptor.attributes.format = .float3
            vertexDescriptor.attributes.offset = 0
            vertexDescriptor.attributes.bufferIndex = 0
            vertexDescriptor.attributes.format = .float2[1]
            vertexDescriptor.attributes.offset = MemoryLayout<SIMD3<Float>>.stride[1]
            vertexDescriptor.attributes.bufferIndex = 0[1]
            vertexDescriptor.layouts.stride = MemoryLayout<Vertex>.stride
            let pipelineDescriptor = MTLRenderPipelineDescriptor()
            pipelineDescriptor.vertexFunction = vertexFunction
            pipelineDescriptor.fragmentFunction = fragmentFunction
            pipelineDescriptor.vertexDescriptor = vertexDescriptor
            pipelineDescriptor.colorAttachments.pixelFormat = view.colorPixelFormat
            pipelineDescriptor.colorAttachments.isBlendingEnabled = true
            pipelineDescriptor.colorAttachments.sourceRGBBlendFactor = .sourceAlpha
            pipelineDescriptor.colorAttachments.sourceAlphaBlendFactor = .sourceAlpha
            pipelineDescriptor.colorAttachments.destinationRGBBlendFactor = .oneMinusSourceAlpha
            pipelineDescriptor.colorAttachments.destinationAlphaBlendFactor = .oneMinusSourceAlpha
            pipelineState = try? device.makeRenderPipelineState(descriptor: pipelineDescriptor)
            let width = 101
            let height = 101
            var vertices: [Vertex] = []
            vertices.reserveCapacity(width * height)
            let size: Float = 4.0
            for y in 0..<height {
                for x in 0..<width {
                    let u = Float(x) / Float(width - 1)
                    let v = Float(y) / Float(height - 1)
                    let px = (u - 0.5) * size
                    let py = (v - 0.5) * size
                    vertices.append(Vertex(position: SIMD3<Float>(px, py, 0.0), uv: SIMD2<Float>(u, v)))
                }
            }
            var indices: [UInt32] = []
            indices.reserveCapacity((width - 1) * (height - 1) * 6)
            for y in 0..<(height - 1) {
                for x in 0..<(width - 1) {
                    let i = UInt32(y * width + x)
                    indices.append(i)
                    indices.append(i + 1)
                    indices.append(i + UInt32(width))
                    indices.append(i + 1)
                    indices.append(i + UInt32(width) + 1)
                    indices.append(i + UInt32(width))
                }
            }
            vertexBuffer = device.makeBuffer(bytes: vertices, length: MemoryLayout<Vertex>.stride * vertices.count, options: .storageModeShared)
            indexBuffer = device.makeBuffer(bytes: indices, length: MemoryLayout<UInt32>.stride * indices.count, options: .storageModeShared)
            numIndices = indices.count
            uniformsBuffer = device.makeBuffer(length: MemoryLayout<Uniforms>.stride, options: .storageModeShared)
        }
        func mtkView(_ view: MTKView, drawableSizeWillChange size: CGSize) {}
        func draw(in view: MTKView) {
            guard let drawable = view.currentDrawable,
                  let commandBuffer = commandQueue?.makeCommandBuffer(),
                  let renderPassDescriptor = view.currentRenderPassDescriptor,
                  let encoder = commandBuffer.makeRenderCommandEncoder(descriptor: renderPassDescriptor),
                  let pipelineState = pipelineState,
                  let vertexBuffer = vertexBuffer,
                  let indexBuffer = indexBuffer,
                  let uniformsBuffer = uniformsBuffer else { return }
            let time = Float(Date().timeIntervalSince(startTime))
            let aspect = Float(view.drawableSize.width / max(view.drawableSize.height, 1))
            let projectionMatrix = matrix_perspective_right_hand_zero_to_one_fov(fovyRadians: Float.pi / 2.4, aspect: aspect, nearZ: 0.1, farZ: 1000.0)
            var modelMatrix = matrix_identity_float4x4
            modelMatrix = matrix_multiply(modelMatrix, matrix_rotation_x(angle: -Float.pi / 4.5))
            let viewMatrix = matrix_look_at_right_hand(eye: SIMD3<Float>(0, 0, 3.5), center: SIMD3<Float>(0, 0, 0), up: SIMD3<Float>(0, 1, 0))
            let modelViewMatrix = matrix_multiply(viewMatrix, modelMatrix)
            var uniforms = Uniforms(projectionMatrix: projectionMatrix, modelViewMatrix: modelViewMatrix, time: time)
            memcpy(uniformsBuffer.contents(), &uniforms, MemoryLayout<Uniforms>.stride)
            encoder.setRenderPipelineState(pipelineState)
            encoder.setVertexBuffer(vertexBuffer, offset: 0, index: 0)
            encoder.setVertexBuffer(uniformsBuffer, offset: 0, index: 1)
            encoder.setFragmentBuffer(uniformsBuffer, offset: 0, index: 0)
            encoder.drawIndexedPrimitives(type: .triangle, indexCount: numIndices, indexType: .uint32, indexBuffer: indexBuffer, indexBufferOffset: 0)
            encoder.endEncoding()
            commandBuffer.present(drawable)
            commandBuffer.commit()
        }
    }
}

let metalShaderSource = """
#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 projectionMatrix;
    float4x4 modelViewMatrix;
    float time;
};

static float2 mod289(float2 x) { return x - floor(x * (1.0/289.0)) * 289.0; }
static float3 mod289(float3 x) { return x - floor(x * (1.0/289.0)) * 289.0; }
static float3 permute(float3 x) { return mod289((x * 34.0 + 1.0) * x); }

static float snoise(float2 v) {
    const float4 C = float4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);
    float2 i  = floor(v + dot(v, C.yy));
    float2 x0 = v - i + dot(i, C.xx);
    float2 i1 = (x0.x > x0.y) ? float2(1.0, 0.0) : float2(0.0, 1.0);
    float4 x12 = x0.xyxy + C.xxzz;
    x12.xy -= i1;
    i = mod289(i);
    float3 p = permute(permute(i.y + float3(0.0, i1.y, 1.0)) + i.x + float3(0.0, i1.x, 1.0));
    float3 m = max(0.5 - float3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
    m = m*m;
    m = m*m;
    float3 x = 2.0 * fract(p * C.www) - 1.0;
    float3 h = abs(x) - 0.5;
    float3 ox = floor(x + 0.5);
    float3 a0 = x - ox;
    m *= 1.79284291400159 - 0.85373472095314 * (a0*a0 + h*h);
    float3 g;
    g.x = a0.x * x0.x + h.x * x0.y;
    g.y = a0.y * x12.x + h.y * x12.y;
    g.z = a0.z * x12.z + h.z * x12.w;
    return 130.0 * dot(m, g);
}

struct VertexIn {
    float3 position [[attribute(0)]];
    float2 uv [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 uv;
};

vertex VertexOut vertex_main(VertexIn in [[stage_in]], constant Uniforms& uniforms [[buffer(1)]]) {
    VertexOut out;
    float3 pos = in.position;
    float n1 = snoise(in.uv * 3.0 + uniforms.time * 0.05);
    float n2 = snoise(in.uv * 10.0 + uniforms.time * 0.02);
    pos.z = (n1 * 0.6 + n2 * 0.4) * 0.2;
    out.position = uniforms.projectionMatrix * uniforms.modelViewMatrix * float4(pos, 1.0);
    out.uv = in.uv;
    return out;
}

fragment float4 fragment_main(VertexOut in [[stage_in]], constant Uniforms& uniforms [[buffer(0)]]) {
    float3 color1 = float3(0.0, 0.2, 0.5);
    float3 color2 = float3(0.0, 0.48, 1.0);
    float n = snoise(in.uv * 3.0 + uniforms.time * 0.05);
    float mix_val = (n + 1.0) * 0.5;
    float3 final_color = mix(color1, color2, mix_val);
    float3 specular = float3(0.8, 0.9, 1.0);
    float shine = smoothstep(0.7, 0.8, n);
    final_color = mix(final_color, specular, shine * 0.5);
    return float4(final_color, 1.0);
}
"""

func matrix_perspective_right_hand_zero_to_one_fov(fovyRadians: Float, aspect: Float, nearZ: Float, farZ: Float) -> simd_float4x4 {
    let ys = 1 / tanf(fovyRadians / 2)
    let xs = ys / aspect
    let zs = farZ / (nearZ - farZ)
    let ws = zs * nearZ
    return simd_float4x4(
        SIMD4<Float>(xs, 0, 0, 0),
        SIMD4<Float>(0, ys, 0, 0),
        SIMD4<Float>(0, 0, zs, -1),
        SIMD4<Float>(0, 0, ws, 0)
    )
}

func matrix_look_at_right_hand(eye: SIMD3<Float>, center: SIMD3<Float>, up: SIMD3<Float>) -> simd_float4x4 {
    let f = simd_normalize(center - eye)
    let s = simd_normalize(simd_cross(f, up))
    let u = simd_cross(s, f)
    return simd_float4x4(
        SIMD4<Float>(s.x, u.x, -f.x, 0),
        SIMD4<Float>(s.y, u.y, -f.y, 0),
        SIMD4<Float>(s.z, u.z, -f.z, 0),
        SIMD4<Float>(-simd_dot(s, eye), -simd_dot(u, eye), simd_dot(f, eye), 1)
    )
}

func matrix_rotation_x(angle: Float) -> simd_float4x4 {
    let c = cos(angle)
    let s = sin(angle)
    return simd_float4x4(
        SIMD4<Float>(1, 0, 0, 0),
        SIMD4<Float>(0, c, s, 0),
        SIMD4<Float>(0, -s, c, 0),
        SIMD4<Float>(0, 0, 0, 1)
    )
}

struct Message: Identifiable {
    let id = UUID()
    let text: AttributedString
    let sender: String
    let isError: Bool
    let isTyping: Bool
}

class ResearchTask: ObservableObject, Identifiable {
    var id: String
    @Published var goal: String
    @Published var status: String
    @Published var progress: Double
    @Published var subAgents: [SubAgent]
    @Published var similarLinks: [LinkItem]
    @Published var webset: [LinkItem]
    @Published var report: AttributedString
    var pollTimer: Timer?
    init(id: String, goal: String) {
        self.id = id
        self.goal = goal
        self.status = "Indítás..."
        self.progress = 0
        self.subAgents = []
        self.similarLinks = []
        self.webset = []
        self.report = AttributedString("")
    }
}

struct SubAgent {
    let name: String
    let status: String
    let progress: Double
}

struct LinkItem {
    let title: String
    let url: String
    let category: String?
}

class ViewModel: ObservableObject {
    @Published var messages: [Message] = []
    @Published var inputText: String = ""
    @Published var currentMode: String = "chat"
    @Published var isSendingDisabled: Bool = true
    @Published var researchTasks: [ResearchTask] = []
    @Published var activeTaskId: String?
    @Published var showResearchOptions: Bool = false
    @Published var pendingResearchGoal: String = ""
    @Published var showPopupMenu: Bool = false
    @Published var researchActive: Bool = false
    let exaApiKey: String = ""
    let exaAnswerUrl = URL(string: "")!
    let exaSearchUrl = URL(string: "")!
    let exaFindSimilarUrl = URL(string: "")!
    let exaResearchBaseUrl = URL(string: "")!
    init() {
        messages.append(Message(text: try! AttributedString(markdown: "Üdvözlöm. Alapértelmezetten az Exa Answer API-t használom. Kattintson a '+' gombra a többi Exa funkció (Keresés, Hasonló link, Mély Kutatás) eléréséhez."), sender: "ai", isError: false, isTyping: false))
    }
    func handleSubmit() {
        let prompt = inputText.trimmingCharacters(in: .whitespacesAndNewlines)
        if prompt.isEmpty { return }
        inputText = ""
        isSendingDisabled = true
        addMessage(text: prompt, sender: "user")
        Task {
            do {
                switch currentMode {
                case "chat", "answer":
                    try await sendExaAnswer(prompt: prompt)
                case "search":
                    try await sendExaSearch(prompt: prompt)
                case "findsimilar":
                    try await sendExaFindSimilar(prompt: prompt)
                case "research":
                    pendingResearchGoal = prompt
                    showResearchOptions = true
                default:
                    break
                }
            } catch {
                updateLastTypingMessage(newText: "Hiba történt: $$error.localizedDescription)", isError: true)
            }
            if currentMode != "research" {
                currentMode = "chat"
            }
        }
    }
    func addMessage(text: String, sender: String, isError: Bool = false, isTyping: Bool = false) {
        var attr: AttributedString
        do {
            attr = try AttributedString(markdown: text)
        } catch {
            attr = AttributedString(text)
        }
        messages.append(Message(text: attr, sender: sender, isError: isError, isTyping: isTyping))
    }
    func addTypingIndicator() {
        messages.append(Message(text: AttributedString(""), sender: "ai", isError: false, isTyping: true))
    }
    func updateLastTypingMessage(newText: String, isError: Bool = false) {
        if let index = messages.lastIndex(where: { $0.isTyping }) {
            var attr: AttributedString
            do {
                attr = try AttributedString(markdown: newText)
            } catch {
                attr = AttributedString(newText)
            }
            messages[index] = Message(text: attr, sender: "ai", isError: isError, isTyping: false)
        } else {
            addMessage(text: newText, sender: "ai", isError: isError)
        }
    }
    func sendExaAnswer(prompt: String) async throws {
        addTypingIndicator()
        var request = URLRequest(url: exaAnswerUrl)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.setValue(exaApiKey, forHTTPHeaderField: "x-api-key")
        let payload: [String: Any] = ["query": prompt, "text": true]
        request.httpBody = try JSONSerialization.data(withJSONObject: payload)
        let (data, _) = try await URLSession.shared.data(for: request)
        let response = try JSONDecoder().decode(ExaAnswerResponse.self, from: data)
        let formatted = formatExaAnswer(response: response)
        updateLastTypingMessage(newText: formatted)
    }
    func sendExaSearch(prompt: String) async throws {
        addTypingIndicator()
        var request = URLRequest(url: exaSearchUrl)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.setValue(exaApiKey, forHTTPHeaderField: "x-api-key")
        let payload: [String: Any] = ["query": prompt, "numResults": 5, "text": true]
        request.httpBody = try JSONSerialization.data(withJSONObject: payload)
        let (data, _) = try await URLSession.shared.data(for: request)
        let response = try JSONDecoder().decode(ExaSearchResponse.self, from: data)
        let formatted = formatExaResults(results: response.results, title: "Keresési Találatok")
        updateLastTypingMessage(newText: formatted)
    }
    func sendExaFindSimilar(prompt: String) async throws {
        addTypingIndicator()
        var request = URLRequest(url: exaFindSimilarUrl)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.setValue(exaApiKey, forHTTPHeaderField: "x-api-key")
        let payload: [String: Any] = ["url": prompt, "numResults": 5, "text": true]
        request.httpBody = try JSONSerialization.data(withJSONObject: payload)
        let (data, _) = try await URLSession.shared.data(for: request)
        let response = try JSONDecoder().decode(ExaSearchResponse.self, from: data)
        let formatted = formatExaResults(results: response.results, title: "Hasonló Linkek")
        updateLastTypingMessage(newText: formatted)
    }
    func formatExaAnswer(response: ExaAnswerResponse) -> String {
        var s = response.answer
        if !response.citations.isEmpty {
            s += "\n\nForrások:\n"
            for citation in response.citations {
                s += "- $$citation.title ?? citation.url)\n"
            }
        }
        return s
    }
    func formatExaResults(results: [ExaResult], title: String) -> String {
        if results.isEmpty {
            return "\nNincsenek találatok.\n"
        }
        var s = "$$title):\n"
        for result in results {
            s += "- $$result.title ?? result.url)\n"
        }
        return s
    }
    func startExaResearchTask(goal: String) {
        let tempId = "temp_$$Date().timeIntervalSince1970)"
        let task = ResearchTask(id: tempId, goal: goal)
        researchTasks.append(task)
        activeTaskId = task.id
        researchActive = true
        addResearchWidgetMessage(task: task)
        Task {
            do {
                var request = URLRequest(url: exaResearchBaseUrl)
                request.httpMethod = "POST"
                request.setValue("application/json", forHTTPHeaderField: "Content-Type")
                request.setValue(exaApiKey, forHTTPHeaderField: "x-api-key")
                let payload: [String: Any] = ["instructions": goal, "model": "exa-research"]
                request.httpBody = try JSONSerialization.data(withJSONObject: payload)
                let (data, _) = try await URLSession.shared.data(for: request)
                let exaTask = try JSONDecoder().decode(ExaResearchResponse.self, from: data)
                await MainActor.run {
                    task.id = exaTask.researchId
                    task.status = exaTask.status
                    task.progress = 5
                    task.subAgents = [SubAgent(name: "Kutató Agent", status: "Inicializálás...", progress: 5)]
                    updateResearchWidget(task: task)
                    pollResearchStatus(task: task)
                    activeTaskId = task.id
                    researchActive = true
                }
            } catch {
                await MainActor.run {
                    task.status = "❌ Hiba a feladat indításakor: $$error.localizedDescription)"
                    task.progress = 0
                    updateResearchWidget(task: task)
                }
            }
        }
    }
    func pollResearchStatus(task: ResearchTask) {
        task.pollTimer = Timer.scheduledTimer(withTimeInterval: 4.0, repeats: true) { _ in
            Task {
                do {
                    var url = self.exaResearchBaseUrl.appendingPathComponent(task.id)
                    if var comps = URLComponents(url: url, resolvingAgainstBaseURL: false) {
                        comps.queryItems = [URLQueryItem(name: "events", value: "true")]
                        if let u = comps.url { url = u }
                    }
                    var request = URLRequest(url: url)
                    request.setValue(self.exaApiKey, forHTTPHeaderField: "x-api-key")
                    let (data, _) = try await URLSession.shared.data(for: request)
                    let exaTask = try JSONDecoder().decode(ExaResearchStatus.self, from: data)
                    await MainActor.run {
                        task.status = exaTask.status
                        if exaTask.status == "running" {
                            task.progress = min(95, task.progress + 5)
                            if !exaTask.events.isEmpty {
                                task.status = exaTask.events.last?.summary ?? "Folyamatban..."
                                task.subAgents = exaTask.events.map { e in
                                    SubAgent(name: e.agentName ?? "Lépés", status: e.summary, progress: e.status == "completed" ? 100 : (e.status == "running" ? 50 : 0))
                                }
                            } else {
                                task.subAgents = [SubAgent(name: "Kutató Agent", status: "Kutatás...", progress: task.progress)]
                            }
                        } else if exaTask.status == "completed" {
                            task.pollTimer?.invalidate()
                            task.progress = 100
                            task.status = "Befejezve"
                            do {
                                task.report = try AttributedString(markdown: exaTask.output)
                            } catch {
                                task.report = AttributedString(exaTask.output)
                            }
                            let citations = exaTask.citations ?? []
                            task.similarLinks = citations.map { LinkItem(title: $0.title ?? $0.url, url: $0.url, category: nil) }
                            task.webset = citations.map { LinkItem(title: $0.title ?? $0.url, url: $0.url, category: "Forrás") }
                            task.subAgents = task.subAgents.map { SubAgent(name: $0.name, status: "Befejezve", progress: 100) }
                        } else if exaTask.status == "failed" {
                            task.pollTimer?.invalidate()
                            task.progress = 100
                            task.status = "❌ Hiba: $$exaTask.error ?? "Ismeretlen hiba")"
                            task.report = AttributedString("A feladat sikertelen: $$exaTask.error ?? "Részletek nem elérhetők.")")
                            task.subAgents = [SubAgent(name: "Agent", status: "Sikertelen", progress: 100)]
                        }
                        self.objectWillChange.send()
                        if self.activeTaskId == task.id {
                        }
                    }
                } catch {
                    await MainActor.run {
                        task.status = "❌ Hiba: Lekérdezés sikertelen ($$error.localizedDescription))."
                        task.pollTimer?.invalidate()
                        self.objectWillChange.send()
                    }
                }
            }
        }
    }
    func addResearchWidgetMessage(task: ResearchTask) {
        var text = ""
        text += "\n"
        text += getIconForType(type: "atom")
        text += "\nAutonóm Kutatási Feladat\n"
        text += "\n"
        text += "\n"
        text += "\n$$task.goal)\n"
        text += "\nStátusz: $$task.status)\n"
        text += "\n"
        text += "\n"
        text += "\n"
        addMessage(text: text, sender: "widget")
    }
    func updateResearchWidget(task: ResearchTask) {
        if let index = messages.lastIndex(where: { $0.sender == "widget" }) {
            var text = ""
            text += "\n"
            text += getIconForType(type: "atom")
            text += "\nAutonóm Kutatási Feladat\n"
            text += "\n"
            text += "\n"
            text += "\n$$task.goal)\n"
            var displayStatus = task.status
            if task.status == "completed" || (task.status == "failed" && task.progress == 100) {
                displayStatus = task.status.contains("Hiba") || task.status.contains("failed") ? "❌ Hiba" : "✅ Befejezve"
            } else if task.status == "running" || task.status == "pending" {
                displayStatus = task.status == "pending" ? "Várakozás..." : "Folyamatban..."
                if !task.subAgents.isEmpty {
                    displayStatus = task.subAgents.last?.status ?? displayStatus
                }
            }
            text += "\nStátusz: $$displayStatus)\n"
            text += "\n"
            text += "\n"
            text += "\n"
            var attr: AttributedString
            do {
                attr = try AttributedString(markdown: text)
            } catch {
                attr = AttributedString(text)
            }
            messages[index] = Message(text: attr, sender: "widget", isError: false, isTyping: false)
        }
    }
    func getIconForType(type: String) -> String {
        switch type {
        case "atom":
            return ""
        case "link":
            return ""
        case "webset":
            return ""
        default:
            return getIconForType(type: "atom")
        }
    }
}

