        Text("TiffyTime")
            .font(.system(size: 16, weight: .semibold))
            .foregroundColor(.textPrimary)
            .frame(maxWidth: .infinity)
            .padding(.top, (UIApplication.shared.connectedScenes.compactMap { ($0 as? UIWindowScene)?.windows.first?.safeAreaInsets.top }.first ?? 0) + 12)
            .padding(.bottom, 12)
            .background(Material.ultraThinMaterial)
            .overlay(Divider(), alignment: .bottom)
    }
    var chatHistory: some View {
        ScrollView {
            LazyVStack(alignment: .leading, spacing: 20) {
                ForEach(viewModel.messages) { message in
                    if message.sender == "widget" {
                        widgetView(message: message)
                    } else {
                        messageView(message: message)
                    }
                }
            }
            .padding(.horizontal, 16)
            .padding(.vertical, 24)
        }
    }
    func messageView(message: Message) -> some View {
        Text(message.text)
            .font(.system(size: 15))
            .padding(.horizontal, 18)
            .padding(.vertical, 12)
            .background(message.sender == "user" ? LinearGradient(colors: [.userBubbleBgStart, .userBubbleBgEnd], startPoint: .topLeading, endPoint: .bottomTrailing) : .aiBubbleBg)
            .foregroundColor(message.sender == "user" ? .white : .textPrimary)
            .clipShape(RoundedRectangle(cornerRadius: 20))
            .shadow(color: .black.opacity(0.2), radius: 4, x: 0, y: 2)
            .frame(maxWidth: UIScreen.main.bounds.width * 0.8, alignment: message.sender == "user" ? .trailing : .leading)
            .alignmentGuide(.leading) { d in message.sender == "user" ? d[.trailing] : d[.leading] }
    }
    func widgetView(message: Message) -> some View {
        Text(message.text)
            .font(.system(size: 15))
            .padding(16)
            .background(.widgetBg)
            .overlay(RoundedRectangle(cornerRadius: 14).stroke(.widgetBorder, lineWidth: 1))
            .frame(maxWidth: UIScreen.main.bounds.width * 0.9)
    }
    var footer: some View {
        HStack(spacing: 10) {
            addButton
            TextField(placeholder, text: $viewModel.inputText)
                .textFieldStyle(RoundedBorderTextFieldStyle())
                .frame(height: 36)
            sendButton
        }
        .padding(.horizontal, 15)
        .padding(.vertical, 10)
        .padding(.bottom, UIApplication.shared.connectedScenes.compactMap { ($0 as? UIWindowScene)?.windows.first?.safeAreaInsets.bottom }.first ?? 0)
        .background(Material.ultraThinMaterial)
        .overlay(Divider(), alignment: .top)
    }
    var placeholder: String {
        switch viewModel.currentMode {
        case "chat": return "Üzenet..."
        case "research": return "Adja meg a kutatás célját..."
        case "search": return "Adja meg a keresési lekérdezést..."
        case "findsimilar": return "Illesszen be egy URL-t a hasonlók kereséséhez..."
        case "answer": return "Tegye fel a kérdését..."
        default: return "Üzenet..."
        }
    }
    var addButton: some View {
        Menu {
            Button {
                viewModel.currentMode = "answer"
                viewModel.showPopupMenu = false
            } label: {
                Label("Közvetlen Válasz", systemImage: "questionmark.circle")
            }
            Button {
                viewModel.currentMode = "search"
                viewModel.showPopupMenu = false
            } label: {
                Label("Egyszerű Keresés", systemImage: "magnifyingglass")
            }
            Button {
                viewModel.currentMode = "findsimilar"
                viewModel.showPopupMenu = false
            } label: {
                Label("Hasonló Link Keresése", systemImage: "link")
            }
            Button {
                viewModel.currentMode = "research"
                viewModel.showPopupMenu = false
            } label: {
                Label("Mély Kutatás (Exa)", systemImage: "atom")
            }
            Button {
                viewModel.addMessage(text: "A fájl feltöltés funkció még nincs implementálva.", sender: "ai")
                viewModel.showPopupMenu = false
            } label: {
                Label("Fájl Feltöltés", systemImage: "paperclip")
            }
        } label: {
            Image(systemName: "plus")
                .font(.system(size: 20))
                .frame(width: 36, height: 36)
                .background(.inputBg)
                .clipShape(Circle())
                .overlay(Circle().stroke(.widgetBorder))
        }
    }
    var sendButton: some View {
        Button {
            viewModel.handleSubmit()
        } label: {
            Image(systemName: viewModel.currentMode == "chat" ? "arrow.up" : "atom")
                .font(.system(size: 20))
                .frame(width: 36, height: 36)
                .background(LinearGradient(colors: [.userBubbleBgStart, .userBubbleBgEnd], startPoint: .topLeading, endPoint: .bottomTrailing))
                .clipShape(Circle())
        }
        .disabled(viewModel.isSendingDisabled)
    }
}

struct ResearchView: View {
    @ObservedObject var viewModel: ViewModel
    var task: ResearchTask? { viewModel.researchTasks.first { $0.id == viewModel.activeTaskId } }
    var body: some View {
        VStack(spacing: 0) {
            researchHeader
            ScrollView {
                VStack(alignment: .leading, spacing: 24) {
                    section(title: "Agentek Státusza") {
                        agentGrid
                    }
                    section(title: "Kutatási Paraméterek") {
                        parametersCard
                    }
                    section(title: "Hasonló Források (Citations)") {
                        similarLinksList
                    }
                    section(title: "Webset (Citations)") {
                        websetList
                    }
                    section(title: "Jelentés") {
                        reportCard
                    }
                }
                .padding(24)
            }
        }
    }
    var researchHeader: some View {
        HStack {
            Button {
                viewModel.researchActive = false
                viewModel.activeTaskId = nil
            } label: {
                Label("Vissza", systemImage: "chevron.left")
                    .foregroundColor(.accentBlue)
            }
            Text(task?.goal.prefix(30) ?? "Kutatási Feladat")
                .font(.system(size: 16, weight: .semibold))
                .lineLimit(1)
                .frame(maxWidth: .infinity)
            Spacer(minLength: 68)
        }
        .padding(.horizontal, 20)
        .padding(.top, (UIApplication.shared.connectedScenes.compactMap { ($0 as? UIWindowScene)?.windows.first?.safeAreaInsets.top }.first ?? 0) + 12)
        .padding(.bottom, 12)
        .background(Material.ultraThinMaterial)
        .overlay(Divider(), alignment: .bottom)
    }
    func section(title: String, @ViewBuilder content: () -> some View) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(title)
                .font(.system(size: 17, weight: .semibold))
                .foregroundColor(.accentBlue)
            content()
        }
    }
    var agentGrid: some View {
        LazyVGrid(columns: [GridItem(.flexible()), GridItem(.flexible())], spacing: 16) {
            ForEach(task?.subAgents ?? [], id: \.name) { agent in
                agentCard(agent: agent)
            }
        }
    }
    func agentCard(agent: SubAgent) -> some View {
        HStack(spacing: 16) {
            DonutProgress(progress: agent.progress)
            VStack(alignment: .leading) {
                Text(agent.name)
                    .font(.system(size: 14, weight: .semibold))
                Text(agent.status)
                    .font(.system(size: 13))
                    .foregroundColor(.textSecondary)
            }
        }
        .padding(20)
        .background(.aiBubbleBg)
        .overlay(RoundedRectangle(cornerRadius: 20).stroke(.widgetBorder))
    }
    var parametersCard: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text("Kutatási Cél")
                .font(.system(size: 14, weight: .semibold))
            Text(task?.goal ?? "")
                .font(.system(size: 15))
            Text("Alkalmazott Beállítások")
                .font(.system(size: 14, weight: .semibold))
            Text("Az Exa agent autonóm módon végzi a kutatást.")
                .font(.system(size: 15))
                .foregroundColor(.textSecondary)
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding(20)
        .background(.aiBubbleBg)
        .overlay(RoundedRectangle(cornerRadius: 20).stroke(.widgetBorder))
    }
    var similarLinksList: some View {
        VStack(spacing: 10) {
            ForEach(task?.similarLinks ?? [], id: \.url) { link in
                linkItem(link: link)
            }
        }
    }
    var websetList: some View {
        VStack(spacing: 10) {
            ForEach(task?.webset ?? [], id: \.url) { item in
                linkItem(link: item)
            }
        }
    }
    func linkItem(link: LinkItem) -> some View {
        HStack(spacing: 12) {
            Image(systemName: "link")
                .frame(width: 36, height: 36)
                .background(.inputBg)
                .clipShape(RoundedRectangle(cornerRadius: 8))
            VStack(alignment: .leading) {
                Text(link.title)
                    .font(.system(size: 14, weight: .medium))
                    .lineLimit(1)
                Text((link.category ?? "") + link.url)
                    .font(.system(size: 13))
                    .foregroundColor(.textSecondary)
                    .lineLimit(1)
            }
        }
        .padding(16)
        .background(.aiBubbleBg)
        .overlay(RoundedRectangle(cornerRadius: 12).stroke(.widgetBorder))
    }
    var reportCard: some View {
        Text(task?.report ?? AttributedString("A jelentés generálása még nem kezdődött el..."))
            .font(.system(size: 15))
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding(20)
            .background(.aiBubbleBg)
            .overlay(RoundedRectangle(cornerRadius: 20).stroke(.widgetBorder))
    }
}

struct DonutProgress: View {
    let progress: Double
    var body: some View {
        ZStack {
            Circle()
                .stroke(Color.inputBg, lineWidth: 6)
            Circle()
                .trim(from: 0, to: progress / 100)
                .stroke(progress == 100 ? Color.green : .accentBlue, lineWidth: 6)
                .rotationEffect(.degrees(-90))
            Text("$$Int(progress))%")
                .font(.system(size: 12, weight: .semibold))
        }
        .frame(width: 48, height: 48)
    }
}

struct ResearchOptionsSheet: View {
    @ObservedObject var viewModel: ViewModel
    @Environment(\.dismiss) var dismiss
    var body: some View {
        VStack(spacing: 20) {
            Rectangle()
                .frame(width: 40, height: 5)
                .foregroundColor(.widgetBorder)
                .clipShape(RoundedRectangle(cornerRadius: 2.5))
            Text("Kutatás Indítása")
                .font(.system(size: 17, weight: .semibold))
            Text(viewModel.pendingResearchGoal)
                .font(.system(size: 15))
                .foregroundColor(.textSecondary)
                .padding(10)
                .background(.inputBg)
                .clipShape(RoundedRectangle(cornerRadius: 8))
                .frame(maxWidth: .infinity)
            Button("Indítás") {
                viewModel.startExaResearchTask(goal: viewModel.pendingResearchGoal)
                dismiss()
            }
            .font(.system(size: 16, weight: .semibold))
            .frame(maxWidth: .infinity)
            .padding(12)
            .background(LinearGradient(colors: [.userBubbleBgStart, .userBubbleBgEnd], startPoint: .topLeading, endPoint: .bottomTrailing))
            .clipShape(RoundedRectangle(cornerRadius: 10))
            Button("Mégse") {
                if let index = viewModel.messages.lastIndex(where: { $0.sender == "user" && $0.text.string == viewModel.pendingResearchGoal }) {
                    viewModel.messages.remove(at: index)
                }
                dismiss()
            }
            .font(.system(size: 15))
            .foregroundColor(.textSecondary)
        }
        .padding(20)
        .padding(.bottom, UIApplication.shared.connectedScenes.compactMap { ($0 as? UIWindowScene)?.windows.first?.safeAreaInsets.bottom }.first ?? 0)
        .background(.headerFooterBg)
        .clipShape(RoundedRectangle(cornerRadius: 20))
    }
}

struct ContentView: View {
    @StateObject var viewModel = ViewModel()
    var body: some View {
        ZStack {
            BackgroundView()
                .opacity(0.15)
                .ignoresSafeArea()
            ChatView(viewModel: viewModel)
                .scaleEffect(viewModel.researchActive ? 0.95 : 1)
                .brightness(viewModel.researchActive ? -0.3 : 0)
                .clipShape(RoundedRectangle(cornerRadius: viewModel.researchActive ? 20 : 0))
                .disabled(viewModel.researchActive)
            if viewModel.researchActive {
                ResearchView(viewModel: viewModel)
                    .transition(.move(edge: .trailing))
            }
        }
        .sheet(isPresented: $viewModel.showResearchOptions) {
            ResearchOptionsSheet(viewModel: viewModel)
                .presentationDetents([.medium])
        }
        .onChange(of: viewModel.inputText) { newValue in
            viewModel.isSendingDisabled = newValue.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        }
    }
}

@main
struct TiffyTimeApp: App {
    var body: some Scene {
        WindowGroup {
            ContentView()
        }
    }
}
